#!/usr/bin/env python3\n\nimport os\nimport sys\nimport django\nfrom django.db import connection\n\n# Add the Django project directory to the Python path\nsys.path.append(os.path.dirname(os.path.dirname(os.path.abspath(__file__))))\n\n# Set up Django\nos.environ.setdefault('DJANGO_SETTINGS_MODULE', 'aiedupro.settings')\ndjango.setup()\n\ndef create_audit_tables():\n    \"\"\"Create audit logs and security events tables\"\"\"\n    \n    sql_commands = [\n        \"\"\"\n        CREATE TABLE IF NOT EXISTS audit_logs (\n            id INT PRIMARY KEY AUTO_INCREMENT,\n            user_id INT,\n            user_type ENUM('student', 'teacher', 'admin'),\n            action VARCHAR(100),\n            resource_type VARCHAR(50),\n            resource_id INT,\n            details JSON,\n            ip_address VARCHAR(45),\n            user_agent TEXT,\n            timestamp TIMESTAMP DEFAULT CURRENT_TIMESTAMP,\n            INDEX idx_user_timestamp (user_id, timestamp),\n            INDEX idx_action (action),\n            INDEX idx_resource (resource_type, resource_id)\n        )\n        \"\"\",\n        \"\"\"\n        CREATE TABLE IF NOT EXISTS security_events (\n            id INT PRIMARY KEY AUTO_INCREMENT,\n            event_type VARCHAR(50),\n            severity ENUM('low', 'medium', 'high', 'critical'),\n            user_id INT,\n            description TEXT,\n            metadata JSON,\n            ip_address VARCHAR(45),\n            resolved BOOLEAN DEFAULT FALSE,\n            timestamp TIMESTAMP DEFAULT CURRENT_TIMESTAMP,\n            INDEX idx_severity_timestamp (severity, timestamp),\n            INDEX idx_user_id (user_id),\n            INDEX idx_resolved (resolved)\n        )\n        \"\"\"\n    ]\n    \n    try:\n        with connection.cursor() as cursor:\n            for sql in sql_commands:\n                print(f\"Executing: {sql[:50]}...\")\n                cursor.execute(sql)\n                print(\"✓ Success\")\n        \n        print(\"\\n✅ All audit tables created successfully!\")\n        \n    except Exception as e:\n        print(f\"❌ Error creating tables: {e}\")\n        return False\n    \n    return True\n\ndef verify_tables():\n    \"\"\"Verify that the tables were created correctly\"\"\"\n    try:\n        with connection.cursor() as cursor:\n            # Check audit_logs table\n            cursor.execute(\"DESCRIBE audit_logs\")\n            audit_columns = cursor.fetchall()\n            print(f\"\\nAudit logs table has {len(audit_columns)} columns\")\n            \n            # Check security_events table\n            cursor.execute(\"DESCRIBE security_events\")\n            security_columns = cursor.fetchall()\n            print(f\"Security events table has {len(security_columns)} columns\")\n            \n            return True\n            \n    except Exception as e:\n        print(f\"❌ Error verifying tables: {e}\")\n        return False\n\nif __name__ == \"__main__\":\n    print(\"🚀 Creating audit and security tables...\")\n    \n    if create_audit_tables():\n        if verify_tables():\n            print(\"\\n🎉 Audit system database setup completed successfully!\")\n            print(\"\\nNext steps:\")\n            print(\"1. Restart your Django server\")\n            print(\"2. The audit middleware will automatically start tracking activities\")\n            print(\"3. Access the admin audit dashboard to monitor activities\")\n        else:\n            print(\"\\n⚠️  Tables created but verification failed\")\n    else:\n        print(\"\\n❌ Failed to create audit tables\")\n        sys.exit(1)